import {adventureHome,closingIntro,adventureRecord} from './journey-view.mjs';
import {taskCardView} from './task-view.mjs';
import {TYPES,MODES,allCards,score,spent,target,thresholds,elapsed} from './core.mjs';
import {themePicker} from './themes.mjs';
export const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
export const button=(text,action,extra='',klass='')=>`<button type="button" class="btn ${klass}" data-action="${action}" ${extra}>${text}</button>`;
export const timeText=ms=>{const m=Math.floor(ms/60000);return m<60?`${m} 分钟`:`${Math.floor(m/60)} 小时 ${m%60} 分钟`;};
export const fmtDate=ts=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric'}).format(ts);
export const currentSlot=(se,id)=>se.slots.find(x=>x.id===id&&['waiting','active','later'].includes(x.status))||se.slots.find(x=>['waiting','active'].includes(x.status));
export function dueText(se,slot){if(se.mode==='free')return '自由模式';const i=se.slots.findIndex(x=>x.id===slot?.id);if(i<0)return '今天的任务已走完';const left=Math.round(i*MODES[se.mode].duration/se.slots.length)-Math.floor(elapsed(se)/60000);return left>0?`建议 ${left} 分钟后，也可以现在抽`:'现在可领取';}
const tag=t=>`<span class="tag ${t}">${TYPES[t].name}</span>`;
const navBtn=(t,r,cl='')=>button(t,'nav',`data-route="${r}"`,cl);
const head=(t,r='home')=>`<div class="page-head"><h1>${t}</h1>${navBtn('返回',r,'text')}</div>`;
const page=(body,wide=false)=>`<div class="page ${wide?'wide':''}">${body}</div>`;
const rules=()=>`<details><summary>怎么玩，怎么算分？</summary><p>场景卡和对话卡每张2分，事件卡每张3分。三类各完成一张，奖励2分，每局一次。两人确认的“惊喜”和“爆笑”各加1分，每种一次。</p><p>结束时各分享一个喜欢的瞬间，再为散步取名，完成收尾加4分。短途默认目标13分，半日20分。完成计划和收尾就能达到，不依赖额外奖励。</p><p>跳过不扣分，目标也不会降低。换过的卡本局不再出现。奖品按最高达成档领取，也可以关闭计分，只管一起走走。</p></details>`;
const placeOptions=(p)=>[['both','室内外都可以'],['indoor','以室内为主'],['outdoor','以户外为主']].map(([v,t])=>`<option value="${v}" ${p===v?'selected':''}>${t}</option>`).join('');
export function filterForm(se){return `<h2>调整接下来的抽卡</h2><form id="filters-form" data-session="${se.id}"><label for="filter-place">活动场景</label><select name="place" id="filter-place">${placeOptions(se.place)}</select><label for="filter-budget">本局购物总预算（元）</label><input id="filter-budget" name="budget" type="number" value="${se.budget}" min="0" max="10000" step="0.01" required><p class="help">已抽出的卡保留原样。新卡按总预算减去已花费的余额筛选。</p><div class="actions"><button type="button" class="btn outline" data-close>取消</button><button class="btn" type="submit">保存调整</button></div></form>`;}
function home(s,ui){return adventureHome(s,ui,{esc,fmtDate,navBtn});}
function setup(s){if(s.session)return page(`${head('还有一段散步没结束')}<div class="panel"><p>可以继续上次，或者先结束这一局再重新开始。</p>${navBtn('继续散步','walk','block')}</div>`);const p=s.preferences;return page(`${head('今天怎么走？')}<form id="setup-form"><div class="mode-options">${Object.entries(MODES).map(([key,m])=>`<label class="mode"><input type="radio" name="mode" value="${key}" ${p.mode===key?'checked':''}><strong>${key==='short'?'短途':key==='half'?'半日':'自由'}</strong><span>${key==='short'?'4张 · 60–90分钟':key==='half'?'7张 · 3–4.5小时':'想走多久都可以'}</span></label>`).join('')}</div><div class="panel"><div class="field-row"><div><label for="place">今天的场景</label><select name="place" id="place">${placeOptions(p.place)}</select></div><div><label for="budget">任务购物预算（元）</label><input id="budget" name="budget" type="number" inputmode="decimal" min="0" max="10000" step="0.01" value="${p.budget}" required></div></div><p class="help">填0只抽零消费任务。不包含交通和日常餐费。</p><label class="check"><input name="scoring" type="checkbox" ${p.scoring?'checked':''}>开启计分与奖励</label><p class="help">不计分也可以玩全部卡片。奖励可在设置里修改。</p></div>${navBtn('看看我们的奖励','settings','text')}<button class="btn block" type="submit">出发</button><p class="footnote">时间只是建议，途中随时暂停、换卡或结束。</p></form>`);}
function taskView(se,x,ui){return taskCardView(se,x,{esc,button,dueText},!ui.swipeSeen);}
function walk(s,ui){const se=s.session;if(!se)return page(`${head('准备开始散步')}<div class="empty"><h2>今天会遇见什么？</h2>${navBtn('开始一局','setup')}</div>`);const sc=score(se),x=currentSlot(se,ui.focusSlot),later=se.slots.filter(x=>x.status==='later');return page(`<div class="page-head"><div><p class="eyebrow">${MODES[se.mode].name}</p><h1>${se.pausedAt?'已暂停':'当前任务'}</h1></div>${button(se.pausedAt?'继续':'暂停','pause',`data-session="${se.id}"`,'outline icon')}</div><div class="score-bar"><div>${se.scoring?`<div class="score-value">${sc.total}<small> / ${target(se)||'自由'} 分</small></div>`:`<div class="score-value">${sc.count}<small> 张任务</small></div>`}<span class="muted small" data-elapsed>${timeText(elapsed(se))}</span></div><div style="text-align:right"><span class="small muted">${se.mode==='free'?`已经抽了 ${se.slots.length} 张`:`已完成 ${sc.count} / ${se.slots.length} 张`}</span><div class="step-dots">${se.slots.slice(-15).map((a,i)=>`<span class="step ${a.status==='done'?'done':''} ${x?.id===a.id?'current':''}" title="${TYPES[a.type].name}">${a.status==='done'?'✓':a.status==='skipped'?'–':i+1}</span>`).join('')}</div></div></div>${se.pausedAt?'<div class="notice">计时已暂停</div>':''}${x?taskView(se,x,ui):`<div class="panel empty"><p class="eyebrow">${se.mode==='free'?'接下来想做什么？':'任务结束'}</p><h2>${se.mode==='free'?'领取新任务':later.length?'还有待办任务':'完成本次冒险'}</h2><p>${se.mode==='free'?'选一种卡片，随时开始。':later.length?'可以点开下方卡片继续，也可以现在收尾。':'分享一个喜欢的瞬间，为今天取个名字。'}</p>${se.mode==='free'?`<div class="actions">${Object.keys(TYPES).map(t=>button(TYPES[t].name,'draw',`data-session="${se.id}" data-type="${t}" ${se.pausedAt?'disabled':''}`,'secondary')).join('')}</div>`:navBtn('结束冒险','finish','block')}</div>`}${later.length?`<div class="panel"><h2>稍后任务 <span class="muted small">${later.length}张</span></h2><div class="list">${later.map(a=>`<div class="list-item">${tag(a.type)}<p style="margin:12px 0">${esc(a.card.text)}</p>${button('现在做这一张','focus',`data-slot="${a.id}"`,'text')}</div>`).join('')}</div></div>`:''}<div class="panel"><div class="list-top"><span class="budget-display">任务已花费 ¥${spent(se)} / 预算 ¥${se.budget}</span>${button('调整','filters',`data-session="${se.id}"`,'text')}</div>${se.scoring?`<hr class="divider"><h3>额外奖励</h3><div class="actions">${button(se.bonuses.surprise?'✓ 小惊喜 +1':'小惊喜 +1','bonus',`data-key="surprise" data-session="${se.id}"`,'secondary')}${button(se.bonuses.laugh?'✓ 笑出声 +1':'笑出声 +1','bonus',`data-key="laugh" data-session="${se.id}"`,'secondary')}</div><p class="help">两人都认可就点一下，每种一局一次。再点可撤回。</p>${sc.trio?'<p class="help">✓ 三类卡片集齐，已自动奖励2分。</p>':''}`:''}<hr class="divider"><div class="actions">${button('撤销最近完成','undo',`data-session="${se.id}" ${sc.count?'':'disabled'}`,'text')}${navBtn('结束这次散步','finish','text')}</div></div>`);}
function finishView(s){const se=s.session;if(!se)return page(`${head('这次散步已经保存')}<div class="empty">到“我们的记录”里看看吧。${navBtn('查看记录','history')}</div>`);const n=se.slots.filter(x=>!['done','skipped'].includes(x.status)).length;return page(`${head('收好这一程','walk')}${closingIntro(se)}<div class="panel closing-form">${n?`<p class="help">还有 ${n} 张未完成，可以留在这次记录里。结束后本局不再计分。</p>`:''}<form id="finish-form" data-session="${se.id}"><label for="walk-name">这次散步的名字</label><input id="walk-name" name="name" maxlength="80" placeholder="比如：绕路也很开心的一天" required><label for="memory">留下一句话（可不填）</label><textarea id="memory" name="memory" maxlength="1000" placeholder="今天想记住的小事…"></textarea><label class="check"><input name="closing" type="checkbox">我们完成了这张收尾卡${se.scoring?'（+4分）':''}</label><button class="btn block" type="submit">保存记录</button></form></div>`);}
function editor(){return `<form id="card-form" class="panel"><h2>自定义任务</h2><div class="field-row"><div><label for="card-type">类型</label><select name="type" id="card-type">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></div><div><label for="card-place">适合哪里</label><select name="place" id="card-place">${placeOptions('both')}</select></div></div><label for="card-text">任务内容</label><textarea id="card-text" name="text" maxlength="200" required placeholder="输入任务内容"></textarea><label for="card-note">小提示（可不填）</label><input id="card-note" name="note" maxlength="500"><div class="field-row"><div><label for="card-minutes">预计分钟</label><input id="card-minutes" name="minutes" type="number" value="5" min="1" max="120" required></div><div><label for="card-cost">费用上限（元）</label><input id="card-cost" name="cost" type="number" value="0" min="0" max="10000" step="0.01" inputmode="decimal" required></div></div><p class="help">上限为0时，这张卡可以在零消费模式出现。</p><div class="spacer"></div><button class="btn block" type="submit">放进卡片盒</button></form>`;}
function library(s,ui){const cards=allCards(s).filter(c=>(ui.libraryType==='all'||c.type===ui.libraryType)&&(!ui.libraryFavorites||s.favorites.includes(c.id)));return page(`${head('我们的卡片盒')}<p class="muted">${allCards(s).length} 张任务，挑喜欢的留给下一次。</p><div class="chips">${[['all','全部'],...Object.entries(TYPES).map(([k,v])=>[k,v.name])].map(([v,t])=>`<button class="chip ${ui.libraryType===v?'active':''}" data-action="filter-type" data-type="${v}">${t}</button>`).join('')}<button class="chip ${ui.libraryFavorites?'active':''}" data-action="filter-favorites">只看喜欢</button></div>${button(ui.customEditor?'收起自定义卡':'＋ 写一张自己的卡','show-editor','','outline')}<div class="spacer"></div>${ui.customEditor?editor():''}<div class="list">${cards.length?cards.map(c=>`<article class="list-item"><div class="list-top">${tag(c.type)}<span class="small muted">${c.id.startsWith('custom-')?'我们写的':c.id.split('-')[1]}</span></div><h3>${esc(c.text)}</h3><p class="help">${esc(c.note)}</p><p class="help">约${c.minutes}分钟 · ${c.cost?`费用上限 ¥${c.cost}`:'零消费'}${s.disabled.includes(c.id)?' · 已停用':''}</p><div class="actions">${button(s.favorites.includes(c.id)?'♥ 已喜欢':'♡ 喜欢','favorite',`data-card="${esc(c.id)}"`,'text')}${button(s.disabled.includes(c.id)?'重新加入抽卡':'暂时不抽这张','disable-card',`data-card="${esc(c.id)}"`,'text')}</div></article>`).join(''):'<div class="empty">还没有符合条件的卡片，换个筛选看看。</div>'}</div>`,true);}
function history(s){return page(`${head('我们的记录')}<div class="list">${s.history.length?s.history.map(h=>`<article class="list-item"><div class="list-top"><span class="small muted">${fmtDate(h.startedAt)} · ${timeText(elapsed(h))}</span><span class="record-score">${h.scoring?`${score(h).total}分`:`${score(h).count}张`}</span></div><h3>${esc(h.name)}</h3>${h.memory?`<p class="muted">${esc(h.memory.slice(0,90))}${h.memory.length>90?'…':''}</p>`:''}${navBtn('查看记录',`detail/${esc(h.id)}`,'text')}</article>`).join(''):`<div class="panel empty"><h2>暂无记录</h2><p>完成冒险后可在这里查看。</p>${navBtn('去走走',s.session?'walk':'setup')}</div>`}</div><p class="footnote">记录只在这部设备上。换手机前，记得在设置里导出备份。</p>`);}
function detail(s,id){const h=s.history.find(x=>x.id===id);if(!h)return page(`${head('没找到这段记录','history')}<p>它可能已在另一页被删除或被备份替换。</p>`);return page(`${head('这一程的回忆','history')}${adventureRecord(h,{esc,fmtDate,timeText,tag})}<div class="record-actions">${navBtn('回到今天','home','block')}${button('删除这段记录','delete-history',`data-id="${esc(h.id)}"`,'text')}</div>`);}
function settings(s,ui){return page(`${head('设置')}<section class="panel"><h2>版本与更新</h2><p class="help">当前版本 <span data-current-version></span></p><p class="status-line" data-update-status role="status">${esc(ui.updateMessage||'联网时会自动检查。')}</p><div class="spacer"></div><div class="actions">${button('检查更新','check-update','','outline')}${button('应用更新并刷新','apply-update','','secondary hidden')}</div><p class="help">更新保留本机散步、分数、皮肤与历史。正在进行的一局也可以更新。</p></section><section class="panel"><h2>主题</h2>${themePicker(s)}</section><form class="panel" id="reward-form"><h2>奖励</h2><p class="help">按从小到大填写。用于下一局，进行中的散步保留原设置。</p>${s.preferences.rewards.map((t,i)=>`<label for="reward-${i}">第${i+1}档奖励</label><input id="reward-${i}" name="reward${i}" value="${esc(t)}" maxlength="80" required>`).join('')}<div class="spacer"></div><button class="btn block secondary" type="submit">保存奖励</button></form><section class="panel"><h2>备份与恢复</h2><p class="help">记录保存在当前浏览器。无痕模式、清理网站数据或更换手机可能让记录丢失。导出备份后可在另一部手机导入。</p><div class="spacer"></div><div class="actions">${button('导出备份','export','','outline')}${button('导入备份','import','','outline')}</div><input type="file" id="backup-file" accept=".json,application/json" class="hidden"><p class="help">导入会替换当前设备全部记录，请先备份。Safari导出的文件通常在“文件”App的下载目录。</p></section><section class="panel"><h2>添加到手机桌面</h2><p><strong>苹果：</strong>在Safari打开网址，点分享按钮，选择“添加到主屏幕”。</p><p><strong>安卓：</strong>在浏览器菜单中选择“安装应用”或“添加到主屏幕”。不同浏览器名称可能不同。</p><p class="help">从桌面图标首次打开时请保持联网，等待离线准备完成。网页和桌面入口的存储可能因浏览器而异，开始前先检查记录。</p><p class="status-line" data-offline>${ui.offlineReady?'✓ 离线内容已准备好':'离线内容尚未准备好，请联网打开并等待片刻。'}</p><div class="spacer"></div>${button('检查离线内容','check-offline','','outline')}<p class="help">锁屏期间不保证准点提醒；回来后会重新计算时间。需要准点提醒时，可以设置手机闹钟。</p></section><section class="panel">${rules()}</section>`);}
export function renderView(s,ui,name='home',id){const views={home:()=>home(s,ui),setup:()=>setup(s),walk:()=>walk(s,ui),finish:()=>finishView(s),library:()=>library(s,ui),history:()=>history(s),settings:()=>settings(s,ui),detail:()=>detail(s,id)};return `<div class="shell" data-page="${esc(name)}"><header class="brand"><div class="brand-name"><span class="brand-mark" aria-hidden="true">↗</span>一起走走</div><div class="brand-tools"><span class="brand-meta">CITYWALK FOR TWO</span>${button('主题','skins','aria-haspopup="dialog"','outline icon skin-trigger')}</div></header>${ui.storageError?`<div role="alert" class="storage-error">${esc(ui.storageError)} ${button('重试','reload','','outline')}</div>`:''}<aside class="notice hidden" data-update-banner aria-label="版本更新"><span>新版本已就绪，进度会保留。</span> ${button('应用更新','apply-update','','outline icon')}</aside><main>${(views[name]||views.home)()}</main></div><nav class="nav" aria-label="主导航">${[['home',s.session?'今天 · 继续':'今天'],['library','卡片盒'],['history','我们的记录'],['settings','设置']].map(([r,t])=>`<button type="button" data-action="nav" data-route="${r}" class="${name===r||r==='home'&&['walk','setup','finish'].includes(name)?'active':''}" ${name===r?'aria-current="page"':''}>${t}</button>`).join('')}</nav>`;}
